export function dynamicOrchestrationLayer(agentMetrics, taskPriority) {
  const computeAllocation = {};
  agentMetrics.forEach(agent => {
    const priorityScore = taskPriority[agent.id] || 0;
    computeAllocation[agent.id] = agent.computeCapacity * priorityScore;
  });
  return computeAllocation;
}